WITH checks AS (SELECT 'customers_is_active_ready' check_name,EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customers' AND column_name='is_active' AND is_nullable='NO') ok UNION ALL SELECT 'deactivation_columns_ready',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customers' AND column_name='deactivated_at') AND EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customers' AND column_name='deactivated_by') UNION ALL SELECT 'lifecycle_guard_ready',EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.customers'::regclass AND tgname='trg_customers_guard_lifecycle_v2' AND NOT tgisinternal) UNION ALL SELECT 'rpc_uses_is_active',COALESCE(pg_get_functiondef(to_regprocedure('public.admin_deactivate_customers_v1(uuid[])')) ILIKE '%is_active=false%',false) UNION ALL SELECT 'rpc_keeps_deleted_at',COALESCE(pg_get_functiondef(to_regprocedure('public.admin_deactivate_customers_v1(uuid[])')) NOT ILIKE '%SET deleted_at=%',false) UNION ALL SELECT 'anon_cannot_execute',NOT has_function_privilege('anon','public.admin_deactivate_customers_v1(uuid[])','EXECUTE') UNION ALL SELECT 'authenticated_can_execute',has_function_privilege('authenticated','public.admin_deactivate_customers_v1(uuid[])','EXECUTE')) SELECT check_name,ok FROM checks WHERE NOT ok ORDER BY check_name;
